-- The two checklists published on 2026-11-16: Finding Your Place as a
-- Stepparent (Stepfamilies) and Moving Back In With Your Parents
-- (Moving Back Home).
-- Generated by `python3 tools/checklists_sql.py --since 2026-11-16`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('finding-your-place-as-a-stepparent', 'Finding Your Place as a Stepparent', 'For a stepparent trying to work out where they fit. It leaves discipline with their parent at first, aims at being a reliable adult rather than a replacement, keeps the rules agreed privately, and gives warmth two years rather than two months.', 'Stepfamilies', '["Let their parent handle the discipline at first — authority you have not earned gets refused.", "Aim to be a reliable adult, not a replacement — the job on offer is smaller and more useful.", "Find one thing you do together that is only yours — a shared thing beats a shared household.", "Never make them choose between you and a parent — they will choose the parent and resent the ask.", "Agree the rules with your partner privately first — a united front gets built off-stage.", "Expect two years rather than two months — warmth here arrives on their schedule, not yours.", "Say nothing about their other parent — whatever you think, it costs you more than it gains.", "Keep time alone with your partner — the couple is what the whole household stands on.", "Let the rejection be about the situation — most of it is not actually about you."]'::jsonb, 'weekly', array['Family', 'Parenting', 'Relationships']::text[], 1, '2026-11-16T16:00:00+00:00'::timestamptz),
  ('moving-back-in-with-your-parents', 'Moving Back In With Your Parents', 'For an adult who has moved back into a parent''s house. It agrees how long out loud, puts money or work in from the first week, keeps your own laundry and cooking, and names the old roles so you can resist sliding into them.', 'Moving Back Home', '["Agree how long this is for, out loud — an open-ended stay turns into a different thing.", "Offer money or work from the first week — paying something keeps you an adult in the house.", "Ask what they actually want to know about your day — assume less reporting than they expect.", "Keep one room or corner that is yours — somewhere to shut a door matters more than space.", "Say the old roles out loud once — being fifteen again is a pull you can name and resist.", "Do your own laundry and cooking from day one — the small jobs are where the slide starts.", "Get out of the house most days — a life that happens elsewhere keeps this bearable.", "Write down what you are saving or sorting — a reason makes it a plan rather than a retreat.", "Tell them one true thing a week — closeness beats politeness, and politeness is the default."]'::jsonb, 'weekly', array['Family', 'Boundaries', 'Life Transitions']::text[], 1, '2026-11-16T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
